begin;
create table public.support_requests(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,category text not null check(category in('account','courses','exams','ai','billing','tutors','organizations')),subject text not null check(length(subject) between 6 and 160),body text not null check(length(body) between 20 and 3000),status text not null default 'open' check(status in('open','in_review','resolved')),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp());
create index support_owner on public.support_requests(user_id,created_at desc);
create table public.notification_preferences(user_id uuid primary key references auth.users(id) on delete cascade,learning_updates boolean not null default false,renewal_reminders boolean not null default false,updated_at timestamptz not null default now());
create table public.email_outbox(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in('registration','verification','password_reset','enrollment','assignment','booking_request','booking_confirmed','booking_cancelled','payment_confirmed','renewal_reminder','membership_expired','organization_invitation')),event_reference text not null check(length(event_reference) between 1 and 200),locale text not null check(locale in('en','ja','ne','hi')),status text not null default 'queued' check(status in('queued','leased','accepted','failed','suppressed')),attempts integer not null default 0 check(attempts between 0 and 5),created_at timestamptz not null default now(),next_attempt_at timestamptz not null default now(),leased_until timestamptz,lease_token uuid,unique(user_id,kind,event_reference));
create index email_due on public.email_outbox(next_attempt_at) where status in('queued','leased');
create table public.email_delivery_logs(id uuid primary key default gen_random_uuid(),outbox_id uuid not null references public.email_outbox(id) on delete cascade,result text not null check(result in('accepted','retry','failed','suppressed')),provider_reference text check(length(provider_reference)<=200),created_at timestamptz not null default now());
create table public.analytics_daily(day date not null default current_date,event text not null check(event in('homepage_visit','course_exploration','registration','lesson_start','lesson_complete','exam_complete','ai_usage','tutor_booking','checkout_start','purchase_verified','organization_registration')),locale text not null check(locale in('en','ja','ne','hi')),source text not null check(source in('client','server')),count bigint not null default 1 check(count between 1 and 10000000),primary key(day,event,locale,source));
create table public.operations_events(minute timestamptz not null,event text not null check(event in('request_failure','api_failure','auth_failure','database_failure','payment_verification_failure','email_failure')),count integer not null default 1 check(count between 1 and 1000000),primary key(minute,event));
create table public.web_vitals_daily(day date not null default current_date,metric text not null check(metric in('LCP','INP','CLS')),bucket text not null check(bucket in('good','needs_improvement','poor')),count bigint not null default 1,primary key(day,metric,bucket));
do $$declare t text;begin foreach t in array array['support_requests','notification_preferences','email_outbox','email_delivery_logs','analytics_daily','operations_events','web_vitals_daily'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy launch_admin_read on public.%I for select to authenticated using(public.is_admin())',t);
end loop;end$$;
create policy support_owner on public.support_requests for select to authenticated using(user_id=auth.uid());
create policy preferences_owner on public.notification_preferences for select to authenticated using(user_id=auth.uid());
create function public.support_submit(p_id uuid,p_category text,p_subject text,p_body text) returns uuid language plpgsql security definer set search_path='' as $$declare old public.support_requests;begin
 if auth.uid() is null then raise exception 'sign_in';end if;
 perform pg_advisory_xact_lock(hashtext('support:'||auth.uid()::text));
 select * into old from public.support_requests where id=p_id;
 if found then if old.user_id<>auth.uid() or old.category<>p_category or old.subject<>p_subject or old.body<>p_body then raise exception 'invalid_retry';end if;return p_id;end if;
 if (select count(*) from public.support_requests where user_id=auth.uid() and created_at>now()-interval '1 day')>=5 then raise exception 'limit';end if;
 insert into public.support_requests(id,user_id,category,subject,body) values(p_id,auth.uid(),p_category,p_subject,p_body);return p_id;
end$$;
create function public.support_review(p_id uuid,p_status text,p_expected timestamptz) returns void language plpgsql security definer set search_path='' as $$begin if not public.is_admin() then raise exception 'forbidden';end if;if p_status not in('open','in_review','resolved') then raise exception 'invalid';end if;update public.support_requests set status=p_status,updated_at=clock_timestamp() where id=p_id and updated_at=p_expected;if not found then raise exception 'stale';end if;end$$;
create function public.notification_preferences_save(p_learning boolean,p_renewal boolean) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'sign_in';end if;insert into public.notification_preferences values(auth.uid(),p_learning,p_renewal,now()) on conflict(user_id) do update set learning_updates=p_learning,renewal_reminders=p_renewal,updated_at=now();end$$;
create function private.launch_count(p_event text,p_user uuid default null) returns void language plpgsql security definer set search_path='' as $$declare l text;begin select preferred_language into l from public.profiles where id=p_user;insert into public.analytics_daily(day,event,locale,source) values(current_date,p_event,coalesce(l,'en'),'server') on conflict(day,event,locale,source) do update set count=least(10000000,public.analytics_daily.count+1);end$$;
create function private.launch_enqueue(p_user uuid,p_kind text,p_event text) returns void language plpgsql security definer set search_path='' as $$declare l text;begin if p_user is null then return;end if;select preferred_language into l from public.profiles where id=p_user;insert into public.email_outbox(user_id,kind,event_reference,locale) values(p_user,p_kind,p_event,coalesce(l,'en')) on conflict do nothing;end$$;
create function private.launch_events() returns trigger language plpgsql security definer set search_path='' as $$begin
 if tg_table_name='course_enrollments' then perform private.launch_enqueue(new.user_id,'enrollment',new.course_id::text);
 elsif tg_table_name='course_assignments' then
 if new.learner_id is not null then perform private.launch_enqueue(new.learner_id,'assignment',new.id::text);else perform private.launch_enqueue(e.user_id,'assignment',new.id::text) from public.class_enrollments e where e.class_id=new.class_id;end if;
 elsif tg_table_name='profiles' then perform private.launch_count('registration',new.id);
 elsif tg_table_name='lesson_progress' then if new.completed_at is not null and (tg_op='INSERT' or old.completed_at is null) then perform private.launch_count('lesson_complete',new.user_id);end if;
 elsif tg_table_name='exam_results' then perform private.launch_count('exam_complete',a.user_id) from public.exam_attempts a where a.id=new.attempt_id;
 elsif tg_table_name='ai_usage' then if new.status='succeeded' and (tg_op='INSERT' or old.status<>'succeeded') then perform private.launch_count('ai_usage',new.user_id);end if;
 elsif tg_table_name='tutor_bookings' then
 if tg_op='INSERT' then perform private.launch_count('tutor_booking',new.learner_id);perform private.launch_enqueue(new.tutor_id,'booking_request',new.id::text);
 elsif new.status<>old.status and new.status in('confirmed','cancelled') then perform private.launch_enqueue(new.learner_id,case when new.status='confirmed' then 'booking_confirmed' else 'booking_cancelled' end,new.id::text);perform private.launch_enqueue(new.tutor_id,case when new.status='confirmed' then 'booking_confirmed' else 'booking_cancelled' end,new.id::text);end if;
 elsif tg_table_name='purchase_orders' then perform private.launch_count('checkout_start',new.user_id);
 elsif tg_table_name='payment_transactions' then perform private.launch_count('purchase_verified',o.user_id) from public.purchase_orders o where o.id=new.order_id;perform private.launch_enqueue(o.user_id,'payment_confirmed',new.id::text) from public.purchase_orders o where o.id=new.order_id;
 elsif tg_table_name='organizations' then perform private.launch_count('organization_registration');
 end if;return new;end$$;
create trigger launch_enrollment after insert on public.course_enrollments for each row execute function private.launch_events();
create trigger launch_assignment after insert on public.course_assignments for each row execute function private.launch_events();
create trigger launch_registration after insert on public.profiles for each row execute function private.launch_events();
create trigger launch_lesson after insert or update on public.lesson_progress for each row execute function private.launch_events();
create trigger launch_exam after insert on public.exam_results for each row execute function private.launch_events();
create trigger launch_ai after insert or update on public.ai_usage for each row execute function private.launch_events();
create trigger launch_booking after insert or update on public.tutor_bookings for each row execute function private.launch_events();
create trigger launch_checkout after insert on public.purchase_orders for each row execute function private.launch_events();
create trigger launch_purchase after insert on public.payment_transactions for each row execute function private.launch_events();
create trigger launch_org after insert on public.organizations for each row execute function private.launch_events();
create function public.launch_client_count(p_event text,p_locale text) returns void language plpgsql security definer set search_path='' as $$begin if p_event not in('homepage_visit','course_exploration','lesson_start') then raise exception 'invalid_event';end if;insert into public.analytics_daily(day,event,locale,source) values(current_date,p_event,p_locale,'client') on conflict(day,event,locale,source) do update set count=least(10000000,public.analytics_daily.count+1);end$$;
create function public.launch_monitor(p_event text) returns void language sql security definer set search_path='' as $$insert into public.operations_events(minute,event) values(date_trunc('minute',now()),p_event) on conflict(minute,event) do update set count=least(1000000,public.operations_events.count+1)$$;
create function public.launch_vital(p_metric text,p_bucket text) returns void language sql security definer set search_path='' as $$insert into public.web_vitals_daily(day,metric,bucket) values(current_date,p_metric,p_bucket) on conflict(day,metric,bucket) do update set count=public.web_vitals_daily.count+1$$;
create function public.launch_email_claim() returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
 update public.email_outbox set status='failed' where status in('queued','leased') and (created_at<now()-interval '23 hours' or attempts>=5) and (leased_until is null or leased_until<now());
 update public.email_outbox o set status='suppressed' where o.status='queued' and ((o.kind in('enrollment','assignment') and not coalesce((select learning_updates from public.notification_preferences where user_id=o.user_id),false)) or (o.kind in('renewal_reminder','membership_expired') and not coalesce((select renewal_reminders from public.notification_preferences where user_id=o.user_id),false)));
 with due as(select id from public.email_outbox where ((status='queued' and next_attempt_at<=now()) or(status='leased' and leased_until<now())) and attempts<5 and created_at>now()-interval '23 hours' order by created_at limit 10 for update skip locked),claimed as(update public.email_outbox o set status='leased',leased_until=now()+interval '5 minutes',attempts=attempts+1,lease_token=gen_random_uuid() from due where o.id=due.id returning o.*) select coalesce(jsonb_agg(to_jsonb(claimed)),'[]') into result from claimed;return result;end$$;
create function public.launch_email_finish(p_id uuid,p_lease uuid,p_result text,p_reference text default null) returns void language plpgsql security definer set search_path='' as $$begin
 if p_result not in('accepted','retry','failed','suppressed') then raise exception 'invalid';end if;
 update public.email_outbox set status=case when p_result='retry' and attempts<5 then 'queued' when p_result='retry' then 'failed' else p_result end,next_attempt_at=now()+make_interval(mins=>power(2,attempts)::integer),leased_until=null,lease_token=null where id=p_id and status='leased' and lease_token=p_lease;
 if not found then raise exception 'stale';end if;insert into public.email_delivery_logs(outbox_id,result,provider_reference) values(p_id,p_result,p_reference);end$$;
create function public.launch_renewal_notifications() returns void language plpgsql security definer set search_path='' as $$begin
 perform private.launch_enqueue(user_id,'renewal_reminder',order_id::text) from public.access_passes where revoked_at is null and ends_at>now() and ends_at<now()+interval '7 days';
 perform private.launch_enqueue(user_id,'membership_expired',order_id::text) from public.access_passes where revoked_at is null and ends_at<=now() and ends_at>now()-interval '1 day';
end$$;
create function public.launch_admin_snapshot() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not public.is_admin() then raise exception 'forbidden';end if;return jsonb_build_object('support',coalesce((select jsonb_agg(x) from(select id,category,subject,body,status,created_at,updated_at from public.support_requests order by created_at desc limit 100)x),'[]'),'analytics',coalesce((select jsonb_agg(x) from(select * from public.analytics_daily where day>current_date-30 order by day desc)x),'[]'),'operations',coalesce((select jsonb_agg(x) from(select event,sum(count)::text count from public.operations_events where minute>now()-interval '1 day' group by event)x),'[]'),'email',coalesce((select jsonb_agg(x) from(select status,count(*)::integer count from public.email_outbox group by status)x),'[]'),'vitals',coalesce((select jsonb_agg(x) from(select metric,bucket,sum(count)::text count from public.web_vitals_daily where day>current_date-30 group by metric,bucket)x),'[]'));end$$;
create function public.launch_schema_health() returns boolean language sql stable security definer set search_path='' as $$select to_regclass('public.support_requests') is not null and not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity)$$;
revoke all on function private.launch_events(),private.launch_count(text,uuid),private.launch_enqueue(uuid,text,text) from public,anon,authenticated;
revoke all on function public.support_submit(uuid,text,text,text),public.support_review(uuid,text,timestamptz),public.notification_preferences_save(boolean,boolean),public.launch_admin_snapshot() from public,anon;
grant execute on function public.support_submit(uuid,text,text,text),public.support_review(uuid,text,timestamptz),public.notification_preferences_save(boolean,boolean),public.launch_admin_snapshot() to authenticated;
revoke all on function public.launch_client_count(text,text),public.launch_monitor(text),public.launch_vital(text,text),public.launch_email_claim(),public.launch_email_finish(uuid,uuid,text,text),public.launch_renewal_notifications(),public.launch_schema_health() from public,anon,authenticated;
do $$begin if exists(select 1 from pg_roles where rolname='service_role') then grant execute on function public.launch_client_count(text,text),public.launch_monitor(text),public.launch_vital(text,text),public.launch_email_claim(),public.launch_email_finish(uuid,uuid,text,text),public.launch_renewal_notifications(),public.launch_schema_health() to service_role;end if;end$$;
commit;
